CREATE TABLE "AgentInstallBatch" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"releaseId" TEXT NOT NULL,"profile" JSONB NOT NULL,"credential" TEXT NOT NULL,"username" TEXT NOT NULL,"port" INTEGER NOT NULL DEFAULT 22,"concurrency" INTEGER NOT NULL DEFAULT 5,"stopOnFailure" BOOLEAN NOT NULL DEFAULT true,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AgentInstallBatch_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AgentInstallBatch_ownerId_createdAt_idx" ON "AgentInstallBatch"("ownerId","createdAt");
CREATE TABLE "AgentInstallTarget" ("id" TEXT NOT NULL,"batchId" TEXT NOT NULL,"assetId" TEXT NOT NULL,"address" TEXT NOT NULL,"hostKey" TEXT NOT NULL,"ordinal" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'WAITING',"installationId" TEXT,"leaseUntil" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0,"detail" TEXT NOT NULL DEFAULT '',"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AgentInstallTarget_pkey" PRIMARY KEY ("id"),CONSTRAINT "AgentInstallTarget_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "AgentInstallBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AgentInstallTarget_batchId_assetId_key" ON "AgentInstallTarget"("batchId","assetId");
CREATE INDEX "AgentInstallTarget_status_leaseUntil_idx" ON "AgentInstallTarget"("status","leaseUntil");
